window.AUTH=window.AUTH||{};window.AUTH["23-1229"]={"d":"23-1229","id":"2024/23-1229","n":"Environmental Protection Agency v. Calumet Shreveport Refining, LLC","briefs":[{"k":"petitioner","label":"Brief of petitioner Environmental Protection Agency","date":"2024-12-13","url":"https://www.supremecourt.gov/DocketPDF/23/23-1229/335166/20241213185232097_23-1229tsUnitedStates.pdf","side":"pet","n":57},{"k":"respondent","label":"Brief of respondents Growth Energy and Renewable Fuels Association supporting petitioner","date":"2024-12-13","url":"https://www.supremecourt.gov/DocketPDF/23/23-1229/335131/20241213170223138_23-1229%20tsGrowthEnergyEtAl.pdf","side":"res","n":53},{"k":"respondent","label":"Brief of respondents Calumet Shreveport Refining, LLC, et al.","date":"2025-01-21","url":"https://www.supremecourt.gov/DocketPDF/23/23-1229/339740/20250121131718802_2025.01.21_No.%2023-1229%20Brief%20for%20the%20Small%20Refinery%20Respondents.pdf","side":"res","n":67},{"k":"reply","label":"Reply of petitioner Environmental Protection Agency","date":"2025-02-20","url":"https://www.supremecourt.gov/DocketPDF/23/23-1229/343262/20250220145737407_CalumetShreveport_merits_reply_final.pdf","side":"pet","n":28}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/605us2r50_g2hk.pdf","tr":true,"items":[{"t":"case","label":"ATK Launch System, Inc. v. United States EPA","cite":"651 F.3d 1194","y":2011,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/651/1194/","op":1,"by":{"0":"21, 27","2":"8, 28","3":"10"}},{"t":"case","label":"(III) Cases—Continued: Alon Refining Krotz Springs, Inc. v. EPA","cite":"936 F.3d 628","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/936/628/","by":{"0":"9"}},{"t":"case","label":"American Road & Transp. Builders Ass’n v. EPA","cite":"705 F.3d 453","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/705/453/","op":2,"by":{"0":"20","2":"7, 28, 39"}},{"t":"case","label":"Bostock v. Clayton County","cite":"590 U.S. 644","y":2020,"id":"2019/17-1618","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"0":"31, 39","1":"26"}},{"t":"case","label":"Chevron U.S.A. Inc. v. EPA","cite":"45 F.4th 380","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/45/380/","sum":"Rejecting petitioner’s argument that EPA’s construction and application to a specific context of “nationally applicable provisions of the Clean Air Act” rendered the agency action itself nationally applicable.","sumSrc":"brief:0","by":{"0":"29","1":"32"}},{"t":"case","label":"FCC v. Pottsville Broadcasting Co.","cite":"309 U.S. 134","y":1940,"id":"scdb/1939-099","sc":1,"op":1,"sum":"1. A lower court's interpretation of its own mandate does not bind this Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27","3":"6"}},{"t":"case","label":"Harrison v. PPG Industries, Inc.","cite":"446 U.S. 578","y":1980,"id":"1979/78-1918","sc":1,"op":1,"sum":"The phrase \"any other final action\" in § 307 (b) (1) is to be construed in accordance with its literal meaning so as to reach any action of the Administrator that is final, not just final actions of the Administrator similar to actions under the specifically enumerated provisions that precede the catchall phrase in the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 25","1":"4, 40"}},{"t":"case","label":"Hunt Ref. Co. v. EPA","cite":"90 F.4th 1107","y":2024,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/90/1107/","op":1,"by":{"0":"13, 20, 24","1":"15-16, 41"}},{"t":"case","label":"Loper Bright Enterprises v. Raimondo","cite":"144 S. Ct. 2244","y":2024,"id":"2023/22-451","sc":1,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"32","1":"18, 40-41","2":"32, 36"}},{"t":"case","label":"Marsh v. Oregon Natural Resources Council","cite":"490 U.S. 360","y":1989,"id":"1988/87-1704","sc":1,"sum":"The Elk Creek Dam is part of a three-dam project designed to control the water supply in Oregon's Rogue River Basin. The Army Corps of Engineers (Corps) completed an Environmental Impact Statement (EIS) for the Elk Creek project in 1971, and, in 1980, released its final Environmental Impact Statement, Supplement No. 1 (FEISS). Since the Rogue River is a premier fishing ground, the FEISS paid special heed to water …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Muldrow v. City of St. Louis","cite":"601 U.S. 346","y":2024,"id":"2023/22-193","sc":1,"sum":"An employee challenging a job transfer under Title VII must show that the transfer brought about some harm with respect to an identifiable term or condition of employment, but that harm need not be significant.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25"}},{"t":"case","label":"National Ass’n of Mfrs. v. Department of Defense","cite":"583 U.S. 109","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"National Environmental Development Ass’n Clean Air Project v. EPA","cite":"891 F.3d 1041","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/891/1041/","by":{"0":"18","1":"42-43","3":"21"}},{"t":"case","label":"Natural Resources Defense Council v. EPA","cite":"465 F.2d 492","y":1972,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/465/492/","by":{"0":"37","1":"28"}},{"t":"case","label":"Natural Resources Defense Council v. EPA","cite":"475 F.2d 968","y":1973,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/475/968/","sum":"Explaining the available-technology determination and corresponding extension action.","sumSrc":"brief:2","by":{"0":"36, 37","1":"28-29","2":"9"}},{"t":"case","label":"Nielsen v. Preap","cite":"586 U.S. 392","y":2019,"id":"2018/16-1363","sc":1,"sum":"The Ninth Circuit’s judgments—that respondents, who are deportable for certain specified crimes, are not subject to 8 U. S. C. §1226(c)(2)’s mandatory-detention requirement because they were not arrested by immigration officials as soon as they were released from jail—are reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25"}},{"t":"case","label":"RMS of Ga., LLC v. EPA","cite":"64 F.4th 1368","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/64/1368/","sum":"Rejecting petitioner’s argument that an allocation of allowances among entities should be considered a “document detailing many smaller individual actions”.","sumSrc":"brief:0","by":{"0":"27, 29"}},{"t":"case","label":"Renewable Fuels Ass’n v. EPA","cite":"948 F.3d 1206","y":2020,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/948/1206/","by":{"0":"6, 7","1":"9","2":"14"}},{"t":"case","label":"Rumsfeld v. Padilla","cite":"542 U.S. 426","y":2004,"id":"2003/03-1027","sc":1,"sum":"Instead, in 5-to-4 opinion written by Chief Justice William H. Rehnquist, the Court found that the case had been improperly filed. Under federal law, a petition for a writ of habeas corpus can only be filed against the person directly responsible for a prisoner's confinement or, put another way, the person with the power to bring the prisoner to court.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Safeco Ins. Co. of Am. v. Burr","cite":"551 U.S. 47","y":2007,"id":"2006/06-84","sc":1,"op":1,"sum":"The Court ruled that insurance companies can be liable for willful violations of the Fair Credit Reporting Act if they show \"reckless disregard\" for the law. The justices held that the meaning of the term \"willful\" is contextually determined.","sumSrc":"Oyez","by":{"0":"31, 35","1":"23"}},{"t":"case","label":"Sierra Club v. EPA","cite":"47 F.4th 738","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/47/738/","op":3,"sum":"Rejecting petitioner’s argument that EPA’s approvals of Texas’s state implementation plans were nationally applicable because EPA had announced a new understanding that would apply in other locations, thereby “effectively amend[ing] the agency’s national implementation regulations”.","sumSrc":"brief:0","by":{"0":"29, 33, 43","2":"10, 31-32"}},{"t":"case","label":"Sinclair Wyoming Ref. Co. v. EPA","cite":"114 F.4th 693","y":2024,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/114/693/","by":{"0":"13, 14, 44","1":"45","2":"11, 18","3":"7, 18, 23"}},{"t":"case","label":"Southern Ill. Power Coop. v. EPA","cite":"863 F.3d 666","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/863/666/","sum":"Rejecting petitioner’s argument that EPA’s designations of nonattainment areas were an “amalgamation of many different locally or regionally applicable actions”.","sumSrc":"brief:0","by":{"0":"20, 21, 29"}},{"t":"case","label":"Vermont Yankee Nuclear Power Corp. v. Natural Resources Defense Council","cite":"435 U.S. 519","y":1978,"id":"1977/76-419","sc":1,"sum":"In No. 76-419, after extensive hearings before the Atomic Safety and Licensing Board (Licensing Board) and over respondents' objections, the Atomic Energy Commission (AEC) granted petitioner Vermont Yankee Nuclear Power Corp. a license to operate a nuclear power plant, and this ruling was affirmed by the Atomic Safety and Licensing Appeal Board (Appeal Board). Subsequently, the AEC, specifically referring to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"West Virginia Chamber of Commerce v. Browner","cite":"166 F.3d 336","y":1998,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/166/336/","sum":"Finding it “clearly regionally applicable” “when the EPA … makes a determination with respect to a particular facility”.","sumSrc":"brief:2","by":{"0":"27","2":"30","3":"10"}},{"t":"case","label":"Whitman v. American Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"0":"20, 24, 25","3":"4"}},{"t":"usc","label":"42 U.S.C. § 7401","url":"https://www.law.cornell.edu/uscode/text/42/7401","stext":{"head":"§7401. Congressional findings and declaration of purpose","paras":[[0,"(a) Findings"],[0,"The Congress finds—"],[1,"(1) that the predominant part of the Nation's population is located in its rapidly expanding metropolitan and other urban areas, which generally cross the boundary lines of local jurisdictions and often extend into two or more States;"],[1,"(2) that the growth in the amount and complexity of air pollution brought about by urbanization, industrial development, and the increasing use of motor vehicles, has resulted in mounting dangers to the public health and welfare, including injury to agricultural crops and livestock, damage to and the deterioration of property, and hazards to air and ground transportation;"],[1,"(3) that air pollution prevention (that is, the reduction or elimination, through any measures, of the amount of pollutants produced or created at the source) and air pollution control at its source is the primary responsibility of States and local governments; and"],[1,"(4) that Federal financial assistance and leadership is essential for the development of cooperative Federal, State, regional, and local programs to prevent and control air pollution."],[0,"(b) Declaration"],[0,"The purposes of this subchapter are—"],[1,"(1) to protect and enhance the quality of the Nation's air resources so as to promote the public health and welfare and the productive capacity of its population;"],[1,"(2) to initiate and accelerate a national research and development program to achieve the prevention and control of air pollution;"],[1,"(3) to provide technical and financial assistance to State and local governments in connection with the development and execution of their air pollution prevention and control programs; and"],[1,"(4) to encourage and assist the development and operation of regional air pollution prevention and control programs."],[0,"(c) Pollution prevention"],[0,"A primary goal of this chapter is to encourage or otherwise promote reasonable Federal, State, and local governmental actions, consistent with the provisions of this chapter, for pollution prevention."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7401?type=usc&year=mostrecent&link-type=html"},"head":"§7401. Congressional findings and declaration of purpose","tname":"The Public Health and Welfare","by":{"0":"2","1":"25"}},{"t":"usc","label":"42 U.S.C. § 7545","url":"https://www.law.cornell.edu/uscode/text/42/7545","subs":["(o)(1)(k)","(o)(2)(A)(i)","(o)(2)(B)(i)","(o)(2)(B)(ii)(III)","(o)(3)","(o)(5)","(o)(5)(B)","(o)(5)(D)","(o)(5)(E)","(o)(9)","(o)(9)(A)","(o)(9)(A)(i)","(o)(9)(A)(ii)(I)","(o)(9)(A)(ii)(II)","(o)(9)(B)","(o)(9)(B)(i)","(o)(9)(B)(ii)","(o)","(o)(7)","(o)(9)(A)(ii)","(o)(9)(B)(iii)"],"stext":{"head":"§7545. Regulation of fuels","paras":[[0,"(a) Authority of Administrator to regulate"],[0,"The Administrator may by regulation designate any fuel or fuel additive (including any fuel or fuel additive used exclusively in nonroad engines or nonroad vehicles) and, after such date or dates as may be prescribed by him, no manufacturer or processor of any such fuel or additive may sell, offer for sale, or introduce into commerce such fuel or additive unless the Administrator has registered such fuel or additive in accordance with subsection (b) of this section."],[0,"(b) Registration requirement"],[0,"(1) For the purpose of registration of fuels and fuel additives, the Administrator shall require—"],[1,"(A) the manufacturer of any fuel to notify him as to the commercial identifying name and manufacturer of any additive contained in such fuel; the range of concentration of any additive in the fuel; and the purpose-in-use of any such additive; and"],[1,"(B) the manufacturer of any additive to notify him as to the chemical composition of such additive."],[0,"(2) For the purpose of registration of fuels and fuel additives, the Administrator shall, on a regular basis, require the manufacturer of any fuel or fuel additive—"],[1,"(A) to conduct tests to determine potential public health and environmental effects of the fuel or additive (including carcinogenic, teratogenic, or mutagenic effects); and"],[1,"(B) to furnish the description of any analytical technique that can be used to detect and measure any additive in such fuel, the recommended range of concentration of such additive, and the recommended purpose-in-use of such additive, and such other information as is reasonable and necessary to determine the emissions resulting from the use of the fuel or additive contained in such fuel, the effect of such fuel or additive on the emission control performance of any vehicle, vehicle engine, nonroad engine or nonroad vehicle, or the extent to which such emissions affect the public health or welfare."],[0,"Tests under subparagraph (A) shall be conducted in conformity with test procedures and protocols established by the Administrator. The result of such tests shall not be considered confidential."],[0,"(3) Upon compliance with the provision of this subsection, including assurances that the Administrator will receive changes in the information required, the Administrator shall register such fuel or fuel additive."],[0,"(4) Study on certain fuel additives and blendstocks.—"],[1,"(A) In general.—Not later than 2 years after August 8, 2005, the Administrator shall—"],[2,"(i) conduct a study on the effects on public health (including the effects on children, pregnant women, minority or low-income communities, and other sensitive populations), air quality, and water resources of increased use of, and the feasibility of using as substitutes for methyl tertiary butyl ether in gasoline—"],[3,"(I) ethyl tertiary butyl ether;"],[3,"(II) tertiary amyl methyl ether;"],[3,"(III) di-isopropyl ether;"],[3,"(IV) tertiary butyl alcohol;"],[3,"(V) other ethers and heavy alcohols, as determined by then 1 Administrator;"],[3,"(VI) ethanol;"],[3,"(VII) iso-octane; and"],[3,"(VIII) alkylates; and"],[2,"(ii) conduct a study on the effects on public health (including the effects on children, pregnant women, minority or low-income communities, and other sensitive populations), air quality, and water resources of the adjustment for ethanol-blended reformulated gasoline to the volatile organic compounds performance requirements that are applicable under paragraphs (1) and (3) of subsection (k); and"],[2,"(iii) submit to the Committee on Environment and Public Works of the Senate and the Committee on Energy and Commerce of the House of Representatives a report describing the results of the studies under clauses (i) and (ii)."],[1,"(B) Contracts for study.—In carrying out this paragraph, the Administrator may enter into one or more contracts with nongovernmental entities such as—"],[2,"(i) the national energy laboratories; and"],[2,"(ii) institutions of higher education (as defined in section 1001 of title 20)."],[0,"(c) Offending fuels and fuel additives; control; prohibition"],[0,"(1) The Administrator may, from time to time on the basis of information obtained under subsection (b) of this section or other information available to him, by regulation, control or prohibit the manufacture, introduction into commerce, offering for sale, or sale of any fuel or fuel additive for use in a motor vehicle, motor vehicle engine, or nonroad engine or nonroad vehicle if, in the judgment of the Administrator, any fuel or fuel additive or any emission product of such fuel or fuel additive causes, or contributes, to air pollution or water pollution (including any degradation in the quality of groundwater) that may reasonably be anticipated to endanger the public health or welfare, or (B) 2 if emission products of such fuel or fuel additive will impair to a significant degree the performance of any emission control device or system which is in general use, or which the Administrator finds has been developed to a point where in a reasonable time it would be in general use were such regulation to be promulgated."],[0,"(2)(A) No fuel, class of fuels, or fuel additive may be controlled or prohibited by the Administrator pursuant to clause (A) of paragraph (1) except after consideration of all relevant medical and scientific evidence available to him, including consideration of other technologically or economically feasible means of achieving emission standards under section 7521 of this title."],[0,"(B) No fuel or fuel additive may be controlled or prohibited by the Administrator pursuant to clause (B) of paragraph (1) except after consideration of available scientific and economic data, including a cost benefit analysis comparing emission control devices or systems which are or will be in general use and require the proposed control or prohibition with emission control devices or systems which are or will be in general use and do not require the proposed control or prohibition. On request of a manufacturer of motor vehicles, motor vehicle engines, fuels, or fuel additives submitted within 10 days of notice of proposed rulemaking, the Administrator shall hold a public hearing and publish findings with respect to any matter he is required to consider under this subparagraph. Such findings shall be published at the time of promulgation of final regulations."],[0,"(C) No fuel or fuel additive may be prohibited by the Administrator under paragraph (1) unless he finds, and publishes such finding, that in his judgment such prohibition will not cause the use of any other fuel or fuel additive which will produce emissions which will endanger the public health or welfare to the same or greater degree than the use of the fuel or fuel additive proposed to be prohibited."],[0,"(3)(A) For the purpose of obtaining evidence and data to carry out paragraph (2), the Administrator may require the manufacturer of any motor vehicle or motor vehicle engine to furnish any information which has been developed concerning the emissions from motor vehicles resulting from the use of any fuel or fuel additive, or the effect of such use on the performance of any emission control device or system."],[0,"(B) In obtaining information under subparagraph (A), section 7607(a) of this title (relating to subpenas) shall be applicable."],[0,"(4)(A) Except as otherwise provided in subparagraph (B) or (C), no State (or political subdivision thereof) may prescribe or attempt to enforce, for purposes of motor vehicle emission control, any control or prohibition respecting any characteristic or component of a fuel or fuel additive in a motor vehicle or motor vehicle engine—"],[1,"(i) if the Administrator has found that no control or prohibition of the characteristic or component of a fuel or fuel additive under paragraph (1) is necessary and has published his finding in the Federal Register, or"],[1,"(ii) if the Administrator has prescribed under paragraph (1) a control or prohibition applicable to such characteristic or component of a fuel or fuel additive, unless State prohibition or control is identical to the prohibition or control prescribed by the Administrator."],[0,"(B) Any State for which application of section 7543(a) of this title has at any time been waived under section 7543(b) of this title may at any time prescribe and enforce, for the purpose of motor vehicle emission control, a control or prohibition respecting any fuel or fuel additive."],[0,"(C)(i) A State may prescribe and enforce, for purposes of motor vehicle emission control, a control or prohibition respecting the use of a fuel or fuel additive in a motor vehicle or motor vehicle engine if an applicable implementation plan for such State under section 7410 of this title so provides. The Administrator may approve such provision in an implementation plan, or promulgate an implementation plan containing such a provision, only if he finds that the State control or prohibition is necessary to achieve the national primary or secondary ambient air quality standard which the plan implements. The Administrator may find that a State control or prohibition is necessary to achieve that standard if no other measures that would bring about timely attainment exist, or if other measures exist and are technically possible to implement, but are unreasonable or impracticable. The Administrator may make a finding of necessity under this subparagraph even if the plan for the area does not contain an approved demonstration of timely attainment."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7545?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§7545. Regulation of fuels","tname":"The Public Health and Welfare","by":{"0":"22, 22, 22, 22, 22, 22, 22, 22, 22, 22, 22, 22, 22, 22, 22, 22, 22","2":"2, 11, 43, 38, 43, 3, 12, 26, 13, 26, 33, 43, 3-4, 22, 25-26, 33, 37, 43, 48, 12, 13, 25, 26, 34, 13, 25, 13, 25, 26, 40","3":"6"}},{"t":"usc","label":"42 U.S.C. § 7607","url":"https://www.law.cornell.edu/uscode/text/42/7607","subs":["(a)","(b)(1)","(d)(9)","(d)(9)(A)"],"stext":{"head":"§7607. Administrative proceedings and judicial review","paras":[[0,"(a) Administrative subpenas; confidentiality; witnesses"],[0,"In connection with any determination under section 7410(f) of this title, or for purposes of obtaining information under section 7521(b)(4) 1 or 7545(c)(3) of this title, any investigation, monitoring, reporting requirement, entry, compliance inspection, or administrative enforcement proceeding under the 2 chapter (including but not limited to section 7413, section 7414, section 7420, section 7429, section 7477, section 7524, section 7525, section 7542, section 7603, or section 7606 of this title),,3 the Administrator may issue subpenas for the attendance and testimony of witnesses and the production of relevant papers, books, and documents, and he may administer oaths. Except for emission data, upon a showing satisfactory to the Administrator by such owner or operator that such papers, books, documents, or information or particular part thereof, if made public, would divulge trade secrets or secret processes of such owner or operator, the Administrator shall consider such record, report, or information or particular portion thereof confidential in accordance with the purposes of section 1905 of title 18, except that such paper, book, document, or information may be disclosed to other officers, employees, or authorized representatives of the United States concerned with carrying out this chapter, to persons carrying out the National Academy of Sciences' study and investigation provided for in section 7521(c) of this title, or when relevant in any proceeding under this chapter. Witnesses summoned shall be paid the same fees and mileage that are paid witnesses in the courts of the United States. In case of contumacy or refusal to obey a subpena served upon any person under this subparagraph,4 the district court of the United States for any district in which such person is found or resides or transacts business, upon application by the United States and after notice to such person, shall have jurisdiction to issue an order requiring such person to appear and give testimony before the Administrator to appear and produce papers, books, and documents before the Administrator, or both, and any failure to obey such order of the court may be punished by such court as a contempt thereof."],[0,"(b) Judicial review"],[0,"(1) A petition for review of action of the Administrator in promulgating any national primary or secondary ambient air quality standard, any emission standard or requirement under section 7412 of this title, any standard of performance or requirement under section 7411 of this title,,3 any standard under section 7521 of this title (other than a standard required to be prescribed under section 7521(b)(1) of this title), any determination under section 7521(b)(5) 1 of this title, any control or prohibition under section 7545 of this title, any standard under section 7571 of this title, any rule issued under section 7413, 7419, or under section 7420 of this title, or any other nationally applicable regulations promulgated, or final action taken, by the Administrator under this chapter may be filed only in the United States Court of Appeals for the District of Columbia. A petition for review of the Administrator's action in approving or promulgating any implementation plan under section 7410 of this title or section 7411(d) of this title, any order under section 7411(j) of this title, under section 7412 of this title, under section 7419 of this title, or under section 7420 of this title, or his action under section 1857c–10(c)(2)(A), (B), or (C) of this title (as in effect before August 7, 1977) or under regulations thereunder, or revising regulations for enhanced monitoring and compliance certification programs under section 7414(a)(3) of this title, or any other final action of the Administrator under this chapter (including any denial or disapproval by the Administrator under subchapter I) which is locally or regionally applicable may be filed only in the United States Court of Appeals for the appropriate circuit. Notwithstanding the preceding sentence a petition for review of any action referred to in such sentence may be filed only in the United States Court of Appeals for the District of Columbia if such action is based on a determination of nationwide scope or effect and if in taking such action the Administrator finds and publishes that such action is based on such a determination. Any petition for review under this subsection shall be filed within sixty days from the date notice of such promulgation, approval, or action appears in the Federal Register, except that if such petition is based solely on grounds arising after such sixtieth day, then any petition for review under this subsection shall be filed within sixty days after such grounds arise. The filing of a petition for reconsideration by the Administrator of any otherwise final rule or action shall not affect the finality of such rule or action for purposes of judicial review nor extend the time within which a petition for judicial review of such rule or action under this section may be filed, and shall not postpone the effectiveness of such rule or action."],[0,"(2) Action of the Administrator with respect to which review could have been obtained under paragraph (1) shall not be subject to judicial review in civil or criminal proceedings for enforcement. Where a final decision by the Administrator defers performance of any nondiscretionary statutory action to a later time, any person may challenge the deferral pursuant to paragraph (1)."],[0,"(c) Additional evidence"],[0,"In any judicial proceeding in which review is sought of a determination under this chapter required to be made on the record after notice and opportunity for hearing, if any party applies to the court for leave to adduce additional evidence, and shows to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the proceeding before the Administrator, the court may order such additional evidence (and evidence in rebuttal thereof) to be taken before the Administrator, in such manner and upon such terms and conditions as to 5 the court may deem proper. The Administrator may modify his findings as to the facts, or make new findings, by reason of the additional evidence so taken and he shall file such modified or new findings, and his recommendation, if any, for the modification or setting aside of his original determination, with the return of such additional evidence."],[0,"(d) Rulemaking"],[0,"(1) This subsection applies to—"],[1,"(A) the promulgation or revision of any national ambient air quality standard under section 7409 of this title,"],[1,"(B) the promulgation or revision of an implementation plan by the Administrator under section 7410(c) of this title,"],[1,"(C) the promulgation or revision of any standard of performance under section 7411 of this title, or emission standard or limitation under section 7412(d) of this title, any standard under section 7412(f) of this title, or any regulation under section 7412(g)(1)(D) and (F) 6 of this title, or any regulation under section 7412(m) or (n) of this title,"],[1,"(D) the promulgation of any requirement for solid waste combustion under section 7429 of this title,"],[1,"(E) the promulgation or revision of any regulation pertaining to any fuel or fuel additive under section 7545 of this title,"],[1,"(F) the promulgation or revision of any aircraft emission standard under section 7571 of this title,"],[1,"(G) the promulgation or revision of any regulation under subchapter IV–A (relating to control of acid deposition),"],[1,"(H) promulgation or revision of regulations pertaining to primary nonferrous smelter orders under section 7419 of this title (but not including the granting or denying of any such order),"],[1,"(I) promulgation or revision of regulations under subchapter VI (relating to stratosphere and ozone protection),"],[1,"(J) promulgation or revision of regulations under part C of subchapter I (relating to prevention of significant deterioration of air quality and protection of visibility),"],[1,"(K) promulgation or revision of regulations under section 7521 of this title and test procedures for new motor vehicles or engines under section 7525 of this title, and the revision of a standard under section 7521(a)(3) of this title,"],[1,"(L) promulgation or revision of regulations for noncompliance penalties under section 7420 of this title,"],[1,"(M) promulgation or revision of any regulations promulgated under section 7541 of this title (relating to warranties and compliance by vehicles in actual use),"],[1,"(N) action of the Administrator under section 7426 of this title (relating to interstate pollution abatement),"],[1,"(O) the promulgation or revision of any regulation pertaining to consumer and commercial products under section 7511b(e) of this title,"],[1,"(P) the promulgation or revision of any regulation pertaining to field citations under section 7413(d)(3) of this title,"],[1,"(Q) the promulgation or revision of any regulation pertaining to urban buses or the clean-fuel vehicle, clean-fuel fleet, and clean fuel programs under part C of subchapter II,"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7607?type=usc&year=mostrecent&link-type=html"},"op":5,"ar":2,"head":"§7607. Administrative proceedings and judicial review","tname":"The Public Health and Welfare","by":{"0":"22, 32, 32, 35","2":"3-4, 6-10, 17, 19, 21-25, 28-32, 34-37, 40-43, 45-50","3":"1-5, 8-15, 18-22"}},{"t":"law","label":"Pub. L. No. 95-95","url":"https://www.govinfo.gov/link/statute/91/776","by":{"0":"2","1":"1-3, 12-13, 16-17, 20-21, 23-32, 34-35, 38-43, 47-48","2":"6"}},{"t":"usc","label":"1 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/1/1","stext":{"head":"§1. Words denoting number, gender, and so forth","paras":[[0,"In determining the meaning of any Act of Congress, unless the context indicates otherwise—"],[1,"words importing the singular include and apply to several persons, parties, or things;"],[1,"words importing the plural include the singular;"],[1,"words importing the masculine gender include the feminine as well;"],[1,"words used in the present tense include the future as well as the present;"],[1,"the words \"insane\" and \"insane person\" shall include every idiot, insane person, and person non compos mentis;"],[1,"the words \"person\" and \"whoever\" include corporations, companies, associations, firms, partnerships, societies, and joint stock companies, as well as individuals;"],[1,"\"officer\" includes any person authorized by law to perform the duties of the office;"],[1,"\"signature\" or \"subscription\" includes a mark when the person making the same intended it as such;"],[1,"\"oath\" includes affirmation, and \"sworn\" includes affirmed;"],[1,"\"writing\" includes printing and typewriting and reproductions of visual symbols by photographing, multigraphing, mimeographing, manifolding, or otherwise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/1/1?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1. Words denoting number, gender, and so forth","tname":"General Provisions","by":{"0":"26","1":"47"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)","(2)(A)"],"by":{"0":"35, 32"}},{"t":"usc","label":"42 U.S.C. § 1857h-5","url":"https://www.law.cornell.edu/uscode/text/42/1857h-5","subs":["(b)(1)(1970)"],"tname":"The Public Health and Welfare","by":{"0":"2, 3, 22, 23, 36","3":"11"}},{"t":"reg","label":"April 2022 Denial of Petitions for Small Refinery Exemptions Under the Renewable Fuel Standard Program, 87 Fed. Reg. 24,300","url":"https://www.govinfo.gov/link/fr/87/24300","by":{"0":"8, 10, 30, 33","1":"10, 12"}},{"t":"reg","label":"41 Fed. Reg. 56,767","url":"https://www.govinfo.gov/link/fr/41/56767","by":{"0":"17, 37, 38, 40","1":"3, 17, 30-31","2":"8, 9","3":"16"}},{"t":"reg","label":"86 Fed. Reg. 70,999","url":"https://www.govinfo.gov/link/fr/86/70999","by":{"0":"7, 43","1":"10","2":"15"}},{"t":"reg","label":"Notice of June 2022 Denial of Petitions for Small Refinery Exemptions Under the Renewable Fuel Standard Program, 87 Fed. Reg. 34,873","url":"https://www.govinfo.gov/link/fr/87/34873","by":{"0":"8, 10, 30, 33","1":"11-12"}},{"t":"case","label":"Page(s) Alaska Department of Environmental Conservation v. EPA","cite":"540 U.S. 461","y":2004,"id":"2003/02-658","sc":1,"sum":"The Court held that the Clean Air Act authorized the EPA to bar the construction of the polluting facility in Alaska. Though Alaska determined the facility's use of \"Low NOx\" met the act's requirement that facilities use \"best available control technology,\" the EPA was reasonable to reject this claim.","sumSrc":"Oyez","by":{"1":"18, 42"}},{"t":"case","label":"American Fuel & Petrochemical Manufacturers v. EPA","cite":"937 F.3d 559","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/937/559/","ar":3,"by":{"1":"8, 37"}},{"t":"case","label":"Americans for Clean Energy v. EPA","cite":"864 F.3d 691","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/864/691/","by":{"1":"5-6, 46","2":"30"}},{"t":"case","label":"Bowen v. Georgetown University Hospital","cite":"488 U.S. 204","y":1988,"id":"1988/87-1097","sc":1,"sum":"Under the Medicare program, the Government reimburses health care providers for expenses incurred in providing medical services to Medicare beneficiaries. The Medicare Act in 42 U. S. C. § 1395x(v)(1)(A) authorizes the Secretary of Health and Human Services (Secretary) to promulgate cost-reimbursement regulations and also provides that \"[s]uch regulations shall... (ii) provide for the making of suitable retroactive …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"39","2":"15"}},{"t":"case","label":"Dayton Power & Light Co. v. EPA","cite":"520 F.2d 703","y":1975,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/520/703/","by":{"1":"29"}},{"t":"case","label":"Direct Marketing Ass’n v. Brohl","cite":"575 U.S. 1","y":2015,"id":"2014/13-1032","sc":1,"sum":"The Court held that the Tax Injunction Act does not prevent federal court review of state tax laws, unless such review could restrict the ability of the state to assess or collect its own taxes.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Elgin v. Department of Treasury","cite":"567 U.S. 1","y":2012,"id":"2011/11-45","sc":1,"sum":"The Court held that the Civil Service Reform Act precludes federal courts' jurisdiction in cases where federal employees seek equitable relief.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Energy Future Coalition v. EPA","cite":"793 F.3d 141","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/793/141/","by":{"1":"37"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Fischer v. United States","cite":"603 U.S. 480","y":2024,"id":"2023/23-5572","sc":1,"sum":"The Court held that 18 U.S.C. § 1512(c), which prohibits obstruction of congressional inquiries and investigations, does not include acts unrelated to investigations and evidence.","sumSrc":"Oyez","by":{"1":"25","2":"8"}},{"t":"case","label":"Fry v. Napoleon Community School","cite":"580 U.S. 154","y":2017,"id":"2016/15-497","sc":1,"op":1,"sum":"The Court determined that the Individuals with Disabilities Education Act’s requirement that plaintiffs exhaust administrative remedies before suing under the Americans with Disabilities Act and the Rehabilitation Act only applies to individuals seeking relief for the denial of a free and appropriate public education.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Growth Energy v. EPA","cite":"5 F.4th 1","y":2021,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/5/1/","by":{"1":"6"}},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"op":1,"sum":"The Court held that the court system cannot disregard the location of a corporation's principal place of business in a multi-state lawsuit.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"HollyFrontier Cheyenne Refining, LLC v. Renewable Fuels Ass’n","cite":"594 U.S. 382","y":2021,"id":"2020/20-472","sc":1,"op":8,"sum":"Under the renewable fuel program’s fuel blending requirements for domestic refineries, a small refinery that previously received a hardship exemption may obtain an “extension” under 42 U. S. C. §7545(o)(9)(B)(i) even if the refinery did not seek a hardship exemption every year after initially doing so.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"6-7, 9","2":"11-12, 14","3":"7, 22"}},{"t":"case","label":"Kaufman v. Nielsen","cite":"896 F.3d 475","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/896/475/","by":{"1":"39"}},{"t":"case","label":"Kentucky v. EPA, __ F.4th __","cite":"2024 WL 5001991","y":2024,"court":"6th Cir. Dec. 6","by":{"1":"33"}},{"t":"case","label":"Milner v. Department of Navy","cite":"562 U.S. 562","y":2011,"id":"2010/09-1163","sc":1,"sum":"The Court held that documents related to the effect of explosions from Navy exercises did not qualify for withholding under Exception 2 of the Freedom of Information Act.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Mississippi ex rel. Hood v. AU Optronics Corp.","cite":"571 U.S. 161","y":2014,"id":"2013/12-1036","sc":1,"op":2,"ar":1,"sum":"The Court ruled that, in order for a case to be removed to a federal district court instead of a state court under the Class Action Fairness Act, at least 100 people must be represented by the lawsuit.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Navarro Savings Ass’n v. Lee","cite":"446 U.S. 458","y":1980,"id":"1979/79-465","sc":1,"op":2,"sum":"Respondents, as individual trustees of a business trust organized under Massachusetts law, may invoke the diversity jurisdiction of the federal courts on the basis of their own citizenship without regard to the citizenship of the trust beneficiaries. A federal court must rest jurisdiction only upon the citizenship of real parties to the controversy, and a trustee is a real party to the controversy for purposes of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Paroline v. United States","cite":"572 U.S. 434","y":2014,"id":"2013/12-8561","sc":1,"sum":"The Court ruled that to recover restitution, either the government or the victim must establish a causal relationship between the defendant's conduct and the victim's harm or damages.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Page(s) Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"sum":"A criminal defendant facing a mandatory minimum sentence is eligible for safety-valve relief under 18 U. S. C. §3553(f)(1) only if the defendant satisfies each of the provision’s three conditions.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"40"}},{"t":"case","label":"Sierra Club v. EPA","cite":"926 F.3d 844","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/926/844/","op":2,"by":{"1":"32-33"}},{"t":"case","label":"Sinclair Wyoming Refining Co. v. EPA","cite":"101 F.4th 871","y":2024,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/101/871/","by":{"1":"8"}},{"t":"case","label":"Texas v. EPA","cite":"829 F.3d 405","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/829/405/","op":5,"by":{"1":"41","2":"10, 24, 29, 31, 32"}},{"t":"case","label":"West Virginia v. EPA","cite":"90 F.4th 323","y":2024,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/90/323/","by":{"1":"33","2":"10, 39, 44"}},{"t":"case","label":"West Virginia v. EPA","cite":"597 U.S. 697","y":2022,"url":"https://supreme.justia.com/cases/federal/us/597/697/","sc":1,"by":{"1":"21"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","by":{"1":"40"}},{"t":"law","label":"Pub. L. No. 91-604","url":"https://www.govinfo.gov/link/statute/84/1676","by":{"1":"27"}},{"t":"law","label":"Pub. L. No. 110-140","url":"https://www.govinfo.gov/link/plaw/110/public/140","by":{"1":"5"}},{"t":"reg","label":"40 C.F.R. § 50.2","url":"https://www.ecfr.gov/current/title-40/section-50.2","by":{"1":"25"}},{"t":"reg","label":"Approval and Promulgation of Implementation Plans, 37 Fed. Reg. 10,842","url":"https://www.govinfo.gov/link/fr/37/10842","by":{"1":"28","3":"2, 17"}},{"t":"reg","label":"Prevention of Significant Air Quality Deterioration, 39 Fed. Reg. 42,510","url":"https://www.govinfo.gov/link/fr/39/42510","by":{"1":"29"}},{"t":"reg","label":"Approval and Promulgation of Implementation Plans, 81 Fed. Reg. 296","url":"https://www.govinfo.gov/link/fr/81/296","by":{"1":"34"}},{"t":"reg","label":"Revised 2023 and Later Model Year Light-Duty Vehicle Greenhouse Gas Emissions Standards, 86 Fed. Reg. 74,434","url":"https://www.govinfo.gov/link/fr/86/74434","by":{"1":"25"}},{"t":"reg","label":"Renewable Fuel Standard (RFS) Program: RFS Annual Rules, 87 Fed. Reg. 39,600","url":"https://www.govinfo.gov/link/fr/87/39600","by":{"1":"8"}},{"t":"case","label":"Clean Water Action Council of Ne. Wis., Inc. v. EPA","cite":"765 F.3d 749","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/765/749/","by":{"2":"29"}},{"t":"case","label":"Cuomo v. Clearing House Ass’n, L.L.C.","cite":"557 U.S. 519","y":2009,"id":"2008/08-453","sc":1,"sum":"The Court found that state officials are not precluded from regulating and enforcing banking activities governed by the Office of the Comptroller.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"Dalton Trucking, Inc. v. EPA","cite":"808 F.3d 875","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/808/875/","by":{"2":"29, 31"}},{"t":"case","label":"Department of Homeland Sec. v. Regents of the Univ. of California","cite":"591 U.S. 1","y":2020,"id":"2019/18-587","sc":1,"sum":"The Court held that the Department of Homeland Security’s decision to rescind the Deferred Action for Childhood Arrivals program was arbitrary and capricious under the Administrative Procedure Act.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"Ergon-West Virginia, Inc. v. EPA","cite":"896 F.3d 600","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/896/600/","by":{"2":"14"}},{"t":"case","label":"Ergon-West Virginia, Inc. v. EPA","cite":"980 F.3d 403","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/980/403/","by":{"2":"14"}},{"t":"case","label":"Kentucky v. EPA","cite":"123 F.4th 447","y":2024,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/123/447/","op":8,"sum":"Rejecting EPA’s argument that its consolidated disapprovals of 21 state implementation plans constituted a single action.","sumSrc":"brief:2","by":{"2":"6, 8, 10, 25, 27-29, 32, 36-38, 40","3":"14"}},{"t":"case","label":"Kentucky v. EPA","cite":"2023 WL 11871967","y":2023,"court":"6th Cir. July 25","by":{"2":"24, 31"}},{"t":"case","label":"Mohamad v. Palestinian Auth.","cite":"566 U.S. 449","y":2012,"id":"2011/11-88","sc":1,"sum":"The Court held that the word \"individual\" in the Torture Victim Protection Act means a natural person and does not impose any liability against organizations.","sumSrc":"Oyez","by":{"2":"32","3":"15"}},{"t":"case","label":"NAACP v. Federal Power Comm’n","cite":"425 U.S. 662","y":1976,"id":"1975/74-1608","sc":1,"sum":"The National Association for the Advancement of Colored People and various other organizations petitioned the Fcderal Power Commission (FPC) to issue a rule \"requiring equal employment opportunity and nondiscrimination in the employment practices of its regulatees.\" The FPC refused, holding that it had no Jurisdiction to issue such a rule. On petition for review, the Court of Appeals, while agreeing that the FPC …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"National Fed’n of Indep. Bus. v. Dep’t of Lab., Occupational Safety & Health Admin.","cite":"595 U.S. 109","y":2022,"url":"https://supreme.justia.com/cases/federal/us/595/109/","sc":1,"by":{"2":"44"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"593 U.S. 155","y":2021,"id":"2020/19-863","sc":1,"sum":"A notice to appear sufficient to trigger the Illegal Immigration Reform and Immigrant Responsibility Act of 1996’s stop-time rule is a single document containing all the information about an individual’s removal hearing specified in 8 U. S. C. §1229(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"2":"49"}},{"t":"case","label":"Sinclair Wyoming Refin. Co. v. EPA","cite":"887 F.3d 986","y":2017,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/887/986/","by":{"2":"14"}},{"t":"case","label":"Texas v. EPA","cite":"983 F.3d 826","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/983/826/","by":{"2":"10"}},{"t":"case","label":"Texas v. EPA","cite":"2011 WL 710598","y":2011,"court":"5th Cir. Feb. 24","by":{"2":"28","3":"10"}},{"t":"case","label":"Texas v. EPA","cite":"2023 WL 7204840","y":2023,"court":"5th Cir. May 1","by":{"2":"10, 24-25, 30, 36"}},{"t":"case","label":"Travis v. United States","cite":"364 U.S. 631","y":1961,"id":"1960/10","sc":1,"sum":"Venue lay only in the District of Columbia, where § 9 (h) and the Board's regulations required the affidavits to be \"on file with the Board,\" and the judgment is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42"}},{"t":"case","label":"United States v. Houlihan","cite":"92 F.3d 1271","y":1996,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/92/1271/","by":{"2":"40"}},{"t":"usc","label":"42 U.S.C. § 1857c-5","url":"https://www.law.cornell.edu/uscode/text/42/1857c-5","subs":["(e)(1973)","(e)(1970)","(e)(1)(1970)","(e)(1)(A)(1970)","(e)(1)(B)(1970)"],"tname":"The Public Health and Welfare","by":{"2":"9","3":"16, 16, 17, 17"}},{"t":"usc","label":"42 U.S.C. § 1857c-10","url":"https://www.law.cornell.edu/uscode/text/42/1857c-10","subs":["(c)(2)"],"by":{"2":"2"}},{"t":"usc","label":"42 U.S.C. § 7410","url":"https://www.law.cornell.edu/uscode/text/42/7410","stext":{"head":"§7410. State implementation plans for national primary and secondary ambient air quality standards","paras":[[0,"(a) Adoption of plan by State; submission to Administrator; content of plan; revision; new sources; indirect source review program; supplemental or intermittent control systems"],[0,"(1) Each State shall, after reasonable notice and public hearings, adopt and submit to the Administrator, within 3 years (or such shorter period as the Administrator may prescribe) after the promulgation of a national primary ambient air quality standard (or any revision thereof) under section 7409 of this title for any air pollutant, a plan which provides for implementation, maintenance, and enforcement of such primary standard in each air quality control region (or portion thereof) within such State. In addition, such State shall adopt and submit to the Administrator (either as a part of a plan submitted under the preceding sentence or separately) within 3 years (or such shorter period as the Administrator may prescribe) after the promulgation of a national ambient air quality secondary standard (or revision thereof), a plan which provides for implementation, maintenance, and enforcement of such secondary standard in each air quality control region (or portion thereof) within such State. Unless a separate public hearing is provided, each State shall consider its plan implementing such secondary standard at the hearing required by the first sentence of this paragraph."],[0,"(2) Each implementation plan submitted by a State under this chapter shall be adopted by the State after reasonable notice and public hearing. Each such plan shall—"],[1,"(A) include enforceable emission limitations and other control measures, means, or techniques (including economic incentives such as fees, marketable permits, and auctions of emissions rights), as well as schedules and timetables for compliance, as may be necessary or appropriate to meet the applicable requirements of this chapter;"],[1,"(B) provide for establishment and operation of appropriate devices, methods, systems, and procedures necessary to—"],[2,"(i) monitor, compile, and analyze data on ambient air quality, and"],[2,"(ii) upon request, make such data available to the Administrator;"],[1,"(C) include a program to provide for the enforcement of the measures described in subparagraph (A), and regulation of the modification and construction of any stationary source within the areas covered by the plan as necessary to assure that national ambient air quality standards are achieved, including a permit program as required in parts C and D;"],[1,"(D) contain adequate provisions—"],[2,"(i) prohibiting, consistent with the provisions of this subchapter, any source or other type of emissions activity within the State from emitting any air pollutant in amounts which will—"],[3,"(I) contribute significantly to nonattainment in, or interfere with maintenance by, any other State with respect to any such national primary or secondary ambient air quality standard, or"],[3,"(II) interfere with measures required to be included in the applicable implementation plan for any other State under part C to prevent significant deterioration of air quality or to protect visibility,"],[2,"(ii) insuring compliance with the applicable requirements of sections 7426 and 7415 of this title (relating to interstate and international pollution abatement);"],[1,"(E) provide (i) necessary assurances that the State (or, except where the Administrator deems inappropriate, the general purpose local government or governments, or a regional agency designated by the State or general purpose local governments for such purpose) will have adequate personnel, funding, and authority under State (and, as appropriate, local) law to carry out such implementation plan (and is not prohibited by any provision of Federal or State law from carrying out such implementation plan or portion thereof), (ii) requirements that the State comply with the requirements respecting State boards under section 7428 of this title, and (iii) necessary assurances that, where the State has relied on a local or regional government, agency, or instrumentality for the implementation of any plan provision, the State has responsibility for ensuring adequate implementation of such plan provision;"],[1,"(F) require, as may be prescribed by the Administrator—"],[2,"(i) the installation, maintenance, and replacement of equipment, and the implementation of other necessary steps, by owners or operators of stationary sources to monitor emissions from such sources,"],[2,"(ii) periodic reports on the nature and amounts of emissions and emissions-related data from such sources, and"],[2,"(iii) correlation of such reports by the State agency with any emission limitations or standards established pursuant to this chapter, which reports shall be available at reasonable times for public inspection;"],[1,"(G) provide for authority comparable to that in section 7603 of this title and adequate contingency plans to implement such authority;"],[1,"(H) provide for revision of such plan—"],[2,"(i) from time to time as may be necessary to take account of revisions of such national primary or secondary ambient air quality standard or the availability of improved or more expeditious methods of attaining such standard, and"],[2,"(ii) except as provided in paragraph (3)(C), whenever the Administrator finds on the basis of information available to the Administrator that the plan is substantially inadequate to attain the national ambient air quality standard which it implements or to otherwise comply with any additional requirements established under this chapter;"],[1,"(I) in the case of a plan or plan revision for an area designated as a nonattainment area, meet the applicable requirements of part D (relating to nonattainment areas);"],[1,"(J) meet the applicable requirements of section 7421 of this title (relating to consultation), section 7427 of this title (relating to public notification), and part C (relating to prevention of significant deterioration of air quality and visibility protection);"],[1,"(K) provide for—"],[2,"(i) the performance of such air quality modeling as the Administrator may prescribe for the purpose of predicting the effect on ambient air quality of any emissions of any air pollutant for which the Administrator has established a national ambient air quality standard, and"],[2,"(ii) the submission, upon request, of data related to such air quality modeling to the Administrator;"],[1,"(L) require the owner or operator of each major stationary source to pay to the permitting authority, as a condition of any permit required under this chapter, a fee sufficient to cover—"],[2,"(i) the reasonable costs of reviewing and acting upon any application for such a permit, and"],[2,"(ii) if the owner or operator receives a permit for such source, the reasonable costs of implementing and enforcing the terms and conditions of any such permit (not including any court costs or other costs associated with any enforcement action),"],[1,"until such fee requirement is superseded with respect to such sources by the Administrator's approval of a fee program under subchapter V; and"],[1,"(M) provide for consultation and participation by local political subdivisions affected by the plan."],[0,"(3)(A) Repealed. Pub. L. 101–549, title I, §101(d)(1), Nov. 15, 1990, 104 Stat. 2409."],[0,"(B) As soon as practicable, the Administrator shall, consistent with the purposes of this chapter and the Energy Supply and Environmental Coordination Act of 1974 [15 U.S.C. 791 et seq.], review each State's applicable implementation plans and report to the State on whether such plans can be revised in relation to fuel burning stationary sources (or persons supplying fuel to such sources) without interfering with the attainment and maintenance of any national ambient air quality standard within the period permitted in this section. If the Administrator determines that any such plan can be revised, he shall notify the State that a plan revision may be submitted by the State. Any plan revision which is submitted by the State shall, after public notice and opportunity for public hearing, be approved by the Administrator if the revision relates only to fuel burning stationary sources (or persons supplying fuel to such sources), and the plan as revised complies with paragraph (2) of this subsection. The Administrator shall approve or disapprove any revision no later than three months after its submission."],[0,"(C) Neither the State, in the case of a plan (or portion thereof) approved under this subsection, nor the Administrator, in the case of a plan (or portion thereof) promulgated under subsection (c), shall be required to revise an applicable implementation plan because one or more exemptions under section 7418 of this title (relating to Federal facilities), enforcement orders under section 7413(d) 1 of this title, suspensions under subsection (f) or (g) (relating to temporary energy or economic authority), orders under section 7419 of this title (relating to primary nonferrous smelters), or extensions of compliance in decrees entered under section 7413(e) 1 of this title (relating to iron- and steel-producing operations) have been granted, if such plan would have met the requirements of this section if no such exemptions, orders, or extensions had been granted."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7410?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§7410. State implementation plans for national primary and secondary ambient air quality standards","tname":"The Public Health and Welfare","by":{"2":"2, 7"}},{"t":"usc","label":"42 U.S.C. § 7411","url":"https://www.law.cornell.edu/uscode/text/42/7411","by":{"2":"1, 2, 6"}},{"t":"usc","label":"42 U.S.C. § 7412","url":"https://www.law.cornell.edu/uscode/text/42/7412","by":{"2":"1, 2, 6"}},{"t":"usc","label":"42 U.S.C. § 7413","url":"https://www.law.cornell.edu/uscode/text/42/7413","by":{"2":"2"}},{"t":"usc","label":"42 U.S.C. § 7414","url":"https://www.law.cornell.edu/uscode/text/42/7414","subs":["(a)(3)"],"by":{"2":"2"}},{"t":"usc","label":"42 U.S.C. § 7419","url":"https://www.law.cornell.edu/uscode/text/42/7419","by":{"2":"2"}},{"t":"usc","label":"42 U.S.C. § 7420","url":"https://www.law.cornell.edu/uscode/text/42/7420","by":{"2":"2"}},{"t":"usc","label":"42 U.S.C. § 7521","url":"https://www.law.cornell.edu/uscode/text/42/7521","by":{"2":"1"}},{"t":"usc","label":"42 U.S.C. § 7571","url":"https://www.law.cornell.edu/uscode/text/42/7571","by":{"2":"2"}},{"t":"reg","label":"40 C.F.R. § 80.1406","url":"https://www.ecfr.gov/current/title-40/section-80.1406","by":{"2":"11"}},{"t":"reg","label":"40 C.F.R. § 80.1426","url":"https://www.ecfr.gov/current/title-40/section-80.1426","by":{"2":"11"}},{"t":"reg","label":"40 C.F.R. § 80.1427","url":"https://www.ecfr.gov/current/title-40/section-80.1427","by":{"2":"11"}},{"t":"reg","label":"40 C.F.R. § 80.1428","url":"https://www.ecfr.gov/current/title-40/section-80.1428","by":{"2":"11"}},{"t":"reg","label":"40 C.F.R. § 80.1429","url":"https://www.ecfr.gov/current/title-40/section-80.1429","by":{"2":"11"}},{"t":"reg","label":"40 C.F.R. § 80.1441","url":"https://www.ecfr.gov/current/title-40/section-80.1441","subs":["(e)(2)"],"by":{"2":"13"}},{"t":"reg","label":"72 Fed. Reg. 23,900","url":"https://www.govinfo.gov/link/fr/72/23900","by":{"2":"12"}},{"t":"reg","label":"75 Fed. Reg. 14,670","url":"https://www.govinfo.gov/link/fr/75/14670","by":{"2":"12"}},{"t":"case","label":"Bruesewitz v. Wyeth LLC","cite":"562 U.S. 223","y":2011,"id":"2010/09-152","sc":1,"op":1,"sum":"The Court held that the National Childhood Vaccine Injury Act shielded manufacturers from certain product liability lawsuits that seek damages for serious health problems suffered by children.","sumSrc":"Oyez","by":{"3":"15"}},{"t":"case","label":"Califano v. Yamasaki","cite":"442 U.S. 682","y":1979,"id":"1978/77-1511","sc":1,"sum":"Section 204 (a) (1) of the Social Security Act (Act) authorizes the Secretary of the Department of Health, Education, and Welfare to recoup erroneous overpayments made to a beneficiary under the old-age, survivors', or disability insurance programs by decreasing future payments to which the overpaid person is entitled. However, § 204 (b) commands that \"there shall be no adjustment of payments to, or recovery by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"7"}},{"t":"case","label":"Caraco Pharmaceutical Laboratories, Ltd. v. Novo Nordisk A/S","cite":"566 U.S. 399","y":2012,"id":"2011/10-844","sc":1,"sum":"The Court held that counterclaims that challenge unpatented uses of generic drugs, even if other approved uses are still under patent, are allowable under the Hatch-Waxman Act.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"EPA v. EME Homer City Generation, L.P.","cite":"572 U.S. 489","y":2014,"id":"2013/12-1182","sc":1,"sum":"The Court held that the EPA has an absolute mandate to require states to meet federal standards set forth in the Clean Air Act.","sumSrc":"Oyez","by":{"3":"11"}},{"t":"case","label":"NLRB v. Bell Aerospace Co.","cite":"416 U.S. 267","y":1974,"id":"1973/72-1598","sc":1,"sum":"On a petition by a labor union for a representation election, the National Labor Relations Board (NLRB) held that the buyers employed by respondent company constituted an appropriate collective-bargaining unit and directed an election. The NLRB stated that even though the buyers might be \"managerial employees\" they were nevprtheless covered by the National Labor Relations Act (NLRA) in the absence of any showing …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"8"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"332 U.S. 194","y":1947,"id":"scdb/1946-133","sc":1,"op":1,"sum":"The new order is sustained. Pp. 196-199, 209.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"8"}},{"t":"case","label":"Yellen v. Confederated Tribes of the Chehalis Reservation","cite":"594 U.S. 338","y":2021,"id":"2020/20-543","sc":1,"op":3,"sum":"Alaska Native Corporations are “Indian tribe[s]” under the Indian Self-Determination and Education Assistance Act and thus eligible for funding available to “Tribal governments” under Title V of the Coronavirus Aid, Relief, and Economic Security Act.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"15"}},{"t":"usc","label":"42 U.S.C. § 7604","url":"https://www.law.cornell.edu/uscode/text/42/7604","subs":["(a)(2)"],"by":{"3":"7"}},{"t":"reg","label":"40 C.F.R. § 81.12-81","url":"https://www.ecfr.gov/current/title-40/section-81.12-81","by":{"3":"12"}}]};